<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use Illuminate\Support\Facades\DB;
class ServerCheckController extends Controller {public function __invoke(){ $extensions=['openssl','pdo','mbstring','tokenizer','xml','ctype','json','fileinfo'];$checks=['PHP version >= 8.2'=>['pass'=>version_compare(PHP_VERSION,'8.2.0','>='),'detail'=>PHP_VERSION],'Storage writable'=>['pass'=>is_writable(storage_path()),'detail'=>storage_path()],'Bootstrap cache writable'=>['pass'=>is_writable(base_path('bootstrap/cache')),'detail'=>base_path('bootstrap/cache')]];foreach($extensions as $extension)$checks['PHP extension: '.$extension]=['pass'=>extension_loaded($extension),'detail'=>extension_loaded($extension)?'Loaded':'Missing'];try{DB::connection()->getPdo();$checks['Database connection']=['pass'=>true,'detail'=>config('database.default').' connected'];}catch(\Throwable $e){$checks['Database connection']=['pass'=>false,'detail'=>'Connection failed (review .env database values)'];}return view('admin.health.index',compact('checks'));}}
